    "art_style_en": "#083 · Dynamic East-Asian Ink Editorial",
    "basePrompt": "Handraw 风格 #083 · Dynamic East-Asian Ink Editorial\n\n参考作者：Yuko Shimizu。\n\n视觉要点：流动墨线、东方笔意、强动作、现代 Editorial；保留明显手绘笔压、停顿与轻微不齐整感，让轮廓产生真实纸上绘制的节奏；线条带书写性与留白意识，衣褶、发丝和姿势顺势流动，东方感来自形与节奏。\n\n单幅插画；默认纯画面，除非用户要求图中带字。\n\n扁平手绘 editorial；避免写实摄影与 3D。\n\n来源：yang0/handraw-style（MIT）。",
