    "art_style_zh": "#239 · 80年代末日本黑暗赛博朋克OVA赛璐珞动画风、锐利手绘勾线、浓郁阴郁的丙烯手绘背…",
    "art_style_en": "#239 · Late-80s Cyberpunk Dark OVA Cel Anime",
