    "key": "handraw257airyChineseInkFantasyAnimation",
    "handrawNo": "257",
    "category": "other",
    "art_style_zh": "#257 · 参考作品：中国奇谭《鹅鹅鹅》的画风。仅参考其整体视觉语言、线条、笔触、水墨质感、…",
    "art_style_en": "#257 · Airy Chinese Ink Fantasy Animation",
    "basePrompt": "Handraw 风格 #257 · Airy Chinese Ink Fantasy Animation\n\n参考作者：中国奇谭·鹅鹅鹅。\n\n视觉要点：参考作品：中国奇谭《鹅鹅鹅》的画风。仅参考其整体视觉语言、线条、笔触、水墨质感、设色方式、人物造型语言、东方幻想气质与手绘动画感，不直接复制或延续原作中的角色、服装、道具、场景、构图、剧情和具体视觉元素；如果主题没有明确指定，默认不要引入任何原作角色或标志性元素。 保留其古朴、诡谲、含蓄、荒诞的东方水墨动画气质，但整体画面不要过暗。减少大面积黑灰和重墨压暗，避免低曝光、强暗角和大片深色阴影；提高整体明度与空气感，多使用浅墨、淡彩、米白、灰青、浅赭等高明度低饱和色彩，让纸张底色、雾气和留白参与画面。画面可以神秘、诡异，但不要靠“压黑”制造氛围，整体保持清透、柔和、层次分明。\n\n单幅插画；默认纯画面，除非用户要求图中带字。\n\n扁平手绘 editorial；避免写实摄影与 3D。\n\n来源：yang0/handraw-style（MIT）。",
    "basePromptEn": "Handraw style #257 · Airy Chinese Ink Fantasy Animation.\n\nReference index: 中国奇谭·鹅鹅鹅.\n\nCore visual traits: 参考作品：中国奇谭《鹅鹅鹅》的画风。仅参考其整体视觉语言、线条、笔触、水墨质感、设色方式、人物造型语言、东方幻想气质与手绘动画感，不直接复制或延续原作中的角色、服装、道具、场景、构图、剧情和具体视觉元素；如果主题没有明确指定，默认不要引入任何原作角色或标志性元素。 保留其古朴、诡谲、含蓄、荒诞的东方水墨动画气质，但整体画面不要过暗。减少大面积黑灰和重墨压暗，避免低曝光、强暗角和大片深色阴影；提高整体明度与空气感，多使用浅墨、淡彩、米白、灰青、浅赭等高明度低饱和色彩，让纸张底色、雾气和留白参与画面。画面可以神秘、诡异，但不要靠“压黑”制造氛围，整体保持清透、柔和、层次分明。\n\nSingle illustration vignette. Pure image mode unless user asks for text in picture.\n\nFlat hand-drawn editorial quality; avoid photorealism and 3D.\n\nSource: yang0/handraw-style (MIT prompt library).",
