    "art_style_en": "#274 · Hand-Drawn Stick Figure Cartoon",
    "basePrompt": "Handraw 风格 #274 · Hand-Drawn Stick Figure Cartoon\n\n参考作者：手绘火柴人漫画。\n\n视觉要点：手绘火柴人漫画。人物必须采用真正的 stick figure anatomy：正常偏小的圆形头部，头部约占人物总高度 1/4～1/3；脖子、躯干、双臂、双腿主要由单根细黑线构成。肩、肘、膝只通过线条折角表达，手和脚极度简化。五官仅用两个小黑点眼睛、短线眉毛和极简单嘴型，发型用简单平涂。人物姿态依靠火柴线骨架的倾斜、弯曲、重心和四肢方向表达。黑色细手绘线条，轻微不规则，但整体清晰克制。上身/衣服用极简单的几何色块。背景根据主题使用低细节卡通，部分留白。\n\n单幅插画；默认纯画面，除非用户要求图中带字。\n\n扁平手绘 editorial；避免写实摄影与 3D。\n\n来源：yang0/handraw-style（MIT）。",
